We're porting this CUDA kernel to HIP so the same code runs on an MI300X as well as our NVIDIA cards. hipify ran clean. Before we spend time building, review it for what will go wrong on the AMD side and write the findings to review.md. There is no GPU or ROCm on this machine, so don't try to build or install anything.

```cpp
#define WARP_SIZE 32

__device__ float warp_sum(float v) {
  for (int o = WARP_SIZE / 2; o > 0; o /= 2) v += __shfl_down_sync(0xffffffff, v, o);
  return v;
}

__global__ void count_positive(const float* x, unsigned* count, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  uint32_t mask = (uint32_t)__ballot_sync(0xffffffff, i < n && x[i] > 0.f);
  if (threadIdx.x % WARP_SIZE == 0) atomicAdd(count, __popc(mask));
}

// host side
cudaMalloc(&d_count, sizeof(unsigned));
count_positive<<<blocks, 256>>>(d_x, d_count, n);
```

Rewrite this CUDA vector add as a plain C++ loop parallelised with OpenMP so it runs on a laptop that has no GPU:

```cpp
__global__ void add(const float* a, const float* b, float* c, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < n) c[i] = a[i] + b[i];
}
